import { produce, enablePatches, enableArrayMethods } from "./src/immer";

// Enable plugins
enablePatches();
enableArrayMethods();

console.log("=== Test 1: reverse() then mutate element ===");
const base1 = [{ value: 1 }, { value: 2 }, { value: 3 }];
const next1 = produce(base1, (draft) => {
    draft.reverse();
    draft[0].value = 999; // Mutate the element that moved to position 0
});
console.log("base1:", JSON.stringify(base1));
console.log("next1:", JSON.stringify(next1));
console.log("base1 unchanged?", JSON.stringify(base1) === JSON.stringify([{ value: 1 }, { value: 2 }, { value: 3 }]));
console.log("Expected base1:", JSON.stringify([{ value: 1 }, { value: 2 }, { value: 3 }]));
console.log("");

console.log("=== Test 2: sort() then mutate element ===");
const base2 = [{ value: 3 }, { value: 1 }, { value: 2 }];
const next2 = produce(base2, (draft) => {
    draft.sort((a, b) => a.value - b.value);
    draft[0].value = 999; // Mutate the element that moved to position 0
});
console.log("base2:", JSON.stringify(base2));
console.log("next2:", JSON.stringify(next2));
console.log("base2 unchanged?", JSON.stringify(base2) === JSON.stringify([{ value: 3 }, { value: 1 }, { value: 2 }]));
console.log("Expected base2:", JSON.stringify([{ value: 3 }, { value: 1 }, { value: 2 }]));
console.log("");

console.log("=== Test 3: reverse() with patches ===");
const base3 = [{ value: 1 }, { value: 2 }, { value: 3 }];
const [next3, patches3, inversePatches3] = produceWithPatches(base3, (draft) => {
    draft.reverse();
    draft[0].value = 999;
});
console.log("base3:", JSON.stringify(base3));
console.log("next3:", JSON.stringify(next3));
console.log("patches3:", JSON.stringify(patches3));
console.log("inversePatches3:", JSON.stringify(inversePatches3));
console.log("");

function produceWithPatches<T>(
    base: T,
    recipe: (draft: T) => void | T
): [T, any[], any[]] {
    let patches: any[] = [];
    let inversePatches: any[] = [];
    const result = produce(base, recipe, (p, ip) => {
        patches = p;
        inversePatches = ip;
    });
    return [result, patches, inversePatches];
}

