import { describe, test, expect } from "vitest";
import { produce, enablePatches, enableArrayMethods, original, isDraft } from "../src/immer";

// Enable plugins for all tests
enablePatches();
enableArrayMethods();

describe("Array reordering methods (reverse/sort) immutability", () => {
  describe("reverse()", () => {
    test("base state not mutated after reverse + element mutation", () => {
      const base = [{ value: 1 }, { value: 2 }, { value: 3 }];
      const next = produce(base, (draft) => {
        draft.reverse();
        draft[0].value = 999;
      });
      expect(base).toEqual([{ value: 1 }, { value: 2 }, { value: 3 }]);
      expect(next).toEqual([{ value: 999 }, { value: 2 }, { value: 1 }]);
    });

    test("reverse only (no element mutation)", () => {
      const base = [{ value: 1 }, { value: 2 }, { value: 3 }];
      const next = produce(base, (draft) => {
        draft.reverse();
      });
      expect(base).toEqual([{ value: 1 }, { value: 2 }, { value: 3 }]);
      expect(next).toEqual([{ value: 3 }, { value: 2 }, { value: 1 }]);
      // Should return same reference if nothing changed
      expect(next).not.toBe(base); // reversed, so it's a new array
    });

    test("multiple elements mutated after reverse", () => {
      const base = [{ value: 1 }, { value: 2 }, { value: 3 }];
      const next = produce(base, (draft) => {
        draft.reverse();
        draft[0].value = 100;
        draft[1].value = 200;
        draft[2].value = 300;
      });
      expect(base).toEqual([{ value: 1 }, { value: 2 }, { value: 3 }]);
      expect(next).toEqual([{ value: 300 }, { value: 200 }, { value: 100 }]);
    });

    test("reverse with nested objects", () => {
      const base = [
        { nested: { a: 1 } },
        { nested: { a: 2 } },
        { nested: { a: 3 } },
      ];
      const next = produce(base, (draft) => {
        draft.reverse();
        draft[0].nested.a = 999;
      });
      expect(base[0].nested.a).toBe(1);
      expect(base[2].nested.a).toBe(3);
      expect(next).toEqual([
        { nested: { a: 3 } },
        { nested: { a: 2 } },
        { nested: { a: 999 } },
      ]);
    });

    test("draft[0] is a proper draft after reverse", () => {
      const base = [{ value: 1 }, { value: 2 }];
      produce(base, (draft) => {
        draft.reverse();
        // After reverse, draft[0] should be a draft proxy
        expect(isDraft(draft[0])).toBe(true);
        expect(original(draft[0]).value).toBe(2); // was at index 1
      });
    });
  });

  describe("sort()", () => {
    test("base state not mutated after sort + element mutation", () => {
      const base = [{ value: 3 }, { value: 1 }, { value: 2 }];
      const next = produce(base, (draft) => {
        draft.sort((a, b) => a.value - b.value);
        draft[0].value = 999;
      });
      expect(base).toEqual([{ value: 3 }, { value: 1 }, { value: 2 }]);
      expect(next).toEqual([{ value: 999 }, { value: 2 }, { value: 3 }]);
    });

    test("sort by string property", () => {
      const base = [
        { name: "Charlie" },
        { name: "Alice" },
        { name: "Bob" },
      ];
      const next = produce(base, (draft) => {
        draft.sort((a, b) => a.name.localeCompare(b.name));
        draft[0].name = "Zara";
      });
      expect(base.map((x) => x.name)).toEqual(["Charlie", "Alice", "Bob"]);
      expect(next.map((x) => x.name)).toEqual(["Alice", "Bob", "Zara"]);
    });

    test("sort with multiple mutations", () => {
      const base = [{ value: 5 }, { value: 1 }, { value: 3 }];
      const next = produce(base, (draft) => {
        draft.sort((a, b) => a.value - b.value);
        draft[0].value = 10;
        draft[2].value = 30;
      });
      expect(base).toEqual([{ value: 5 }, { value: 1 }, { value: 3 }]);
      expect(next).toEqual([{ value: 10 }, { value: 3 }, { value: 30 }]);
    });
  });

  describe("Combined operations", () => {
    test("reverse then sort", () => {
      const base = [{ value: 3 }, { value: 1 }, { value: 2 }];
      const next = produce(base, (draft) => {
        draft.reverse();
        draft.sort((a, b) => a.value - b.value);
        draft[0].value = 999;
      });
