    test("empty array", () => {
      const base: any[] = [];
      const next = produce(base, (draft) => {
        draft.reverse();
      });
      expect(next).toEqual([]);
    });

    test("single element array", () => {
      const base = [{ value: 1 }];
      const next = produce(base, (draft) => {
        draft.reverse();
        draft[0].value = 999;
      });
      expect(base).toEqual([{ value: 1 }]);
      expect(next).toEqual([{ value: 999 }]);
    });

    test("two element array", () => {
      const base = [{ value: 1 }, { value: 2 }];
      const next = produce(base, (draft) => {
        draft.reverse();
        draft[0].value = 999;
      });
      expect(base).toEqual([{ value: 1 }, { value: 2 }]);
