test("sort by string property", () => {
  const base = [
    { name: "Charlie" },
    { name: "Alice" },
    { name: "Bob" },
  ];
  const next = produce(base, (draft) => {
    draft.sort((a, b) => a.name.localeCompare(b.name));
    draft[0].name = "Zara";
  });
  expect(base.map((x) => x.name)).toEqual(["Charlie", "Alice", "Bob"]);
  expect(next.map((x) => x.name)).toEqual(["Alice", "Bob", "Zara"]);
});

