test("multiple elements mutated after reverse", () => {
  const base = [{ value: 1 }, { value: 2 }, { value: 3 }];
  const next = produce(base, (draft) => {
    draft.reverse();
    draft[0].value = 100;
    draft[1].value = 200;
    draft[2].value = 300;
  });
  expect(base).toEqual([{ value: 1 }, { value: 2 }, { value: 3 }]);
  expect(next).toEqual([{ value: 300 }, { value: 200 }, { value: 100 }]);
});

edits.newText:
test("multiple elements mutated after reverse", () => {
  const base = [{ value: 1 }, { value: 2 }, { value: 3 }];
  const next = produce(base, (draft) => {
    draft.reverse(); // Now draft[0] is base[2], draft[1] is base[1], draft[2] is base[0]
    draft[0].value = 100; // Modifies what was base[2]
    draft[1].value = 200; // Modifies what was base[1]
    draft[2].value = 300; // Modifies what was base[0]
  });
  expect(base).toEqual([{ value: 1 }, { value: 2 }, { value: 3 }]);
  expect(next).toEqual([{ value: 100 }, { value: 200 }, { value: 300 }]);
});

