import { produce, enablePatches, enableArrayMethods } from "./src/immer";

enablePatches();
enableArrayMethods();

// Test case from ISSUE.md
const base = [{ value: 1 }, { value: 2 }, { value: 3 }];
const next = produce(base, (draft) => {
    draft.reverse();
    draft[0].value = 999;
});

// Verify base is not mutated
console.log("Base state:", JSON.stringify(base));
console.log("Expected:", JSON.stringify([{ value: 1 }, { value: 2 }, { value: 3 }]));
console.log("Base unchanged:", JSON.stringify(base) === JSON.stringify([{ value: 1 }, { value: 2 }, { value: 3 }]));

// Verify next has correct values
console.log("\nNext state:", JSON.stringify(next));
console.log("Expected:", JSON.stringify([{ value: 999 }, { value: 2 }, { value: 1 }]));
console.log("Next correct:", JSON.stringify(next) === JSON.stringify([{ value: 999 }, { value: 2 }, { value: 1 }]));

// Summary
const passed = 
    JSON.stringify(base) === JSON.stringify([{ value: 1 }, { value: 2 }, { value: 3 }]) &&
    JSON.stringify(next) === JSON.stringify([{ value: 999 }, { value: 2 }, { value: 1 }]);

console.log("\n" + (passed ? "✅ FIX VERIFIED: Bug is fixed!" : "❌ FIX FAILED: Bug still exists"));
process.exit(passed ? 0 : 1);

