test("sort by string property", () => {
  const base = [
    { name: "Charlie" },
    { name: "Alice" },
    { name: "Bob" },
  ];
  const next = produce(base, (draft) => {
    draft.sort((a, b) => a.name.localeCompare(b.name));
    // After sort: [Alice, Bob, Charlie]
    draft[0].name = "Zara"; // Modifies Alice -> Zara
